solution:
class LRUCache {
  constructor(capacity, now = () => 0) {
    this.capacity = capacity;
    this.now = now;
    this.map = new Map(); // insertion order = recency order (oldest first)
  }

  get(key) {
    const entry = this.map.get(key);
    if (!entry) return undefined;
    if (this.now() >= entry.expiresAt) {
      this.map.delete(key);           // lazy expiry
      return undefined;
    }
    this.map.delete(key);             // move to the "most recent" end
    this.map.set(key, entry);
    return entry.value;
  }

  set(key, value, ttlMs) {
    const expiresAt = ttlMs === undefined ? Infinity : this.now() + ttlMs;
    if (this.map.has(key)) this.map.delete(key);
    else if (this.map.size >= this.capacity) {
      const oldest = this.map.keys().next().value;
      this.map.delete(oldest);
    }
    this.map.set(key, { value, expiresAt });
  }

  size() {
    return this.map.size;
  }
}

tests.code:
const c = new LRUCache(3);
c.set('book:1', 'Charlotte\'s Web');
c.set('book:2', 'Holes');
assertEqual(c.get('book:1'), 'Charlotte\'s Web');
assertEqual(c.get('book:9'), undefined);
assertEqual(c.size(), 2);

const c = new LRUCache(2);
c.set('a', 1); c.set('b', 2); c.set('c', 3);
assertEqual(c.get('a'), undefined, 'a was oldest, should be evicted');
assertEqual(c.get('b'), 2);
assertEqual(c.get('c'), 3);
assertEqual(c.size(), 2);

const c = new LRUCache(2);
c.set('a', 1); c.set('b', 2);
c.get('a');
c.set('c', 3);
assertEqual(c.get('b'), undefined, 'b should be evicted, a was read recently');
assertEqual(c.get('a'), 1);

const c = new LRUCache(2);
c.set('a', 1); c.set('b', 2);
c.set('a', 10);
assertEqual(c.size(), 2);
assertEqual(c.get('a'), 10);
c.set('c', 3);
assertEqual(c.get('b'), undefined, 'b is now least recent');
assertEqual(c.get('a'), 10);

let t = 1000;
const c = new LRUCache(5, () => t);
c.set('session', 'xyz', 100);
t = 1099; assertEqual(c.get('session'), 'xyz');
t = 1100; assertEqual(c.get('session'), undefined);
assertEqual(c.size(), 0, 'expired entry should be removed');

let t = 0;
const c = new LRUCache(5, () => t);
c.set('config', 'v1');
t = 10 ** 12;
assertEqual(c.get('config'), 'v1');

let t = 0;
const c = new LRUCache(5, () => t);
c.set('k', 'old', 100);
t = 90; c.set('k', 'new', 100);
t = 150; assertEqual(c.get('k'), 'new', 'ttl should restart at t=90');
t = 190; assertEqual(c.get('k'), undefined);

const c = new LRUCache(1);
c.set('x', 1); c.set('y', 2);
assertEqual(c.get('x'), undefined);
assertEqual(c.get('y'), 2);
assertEqual(c.size(), 1);
